// These operations instantiate helpers from the original guild storage/shop
// containers. They are compilation drivers, never registered as runtime hooks.
void Unk_GuildDriveOther(guilddef4::ProductVec& products, guilddef4::HistDeque& history,
                        guilddef4::MapStorage2& storage, guilddef4::MapReward& rewards,
                        const guilddef4::TP<guilddef4::Hist>& entry) {
    Unk_DriveVector(products, guilddef4::TP<CNpcShopProductProxy>());
    history.push_back(entry);
    history.clear();
    Unk_DriveMap(storage, std::pair<__int64, int>());
    Unk_DriveMap(rewards, 0);
}
void Unk_GuildDriveProxy(std::_Container_proxy* destination, std::_Container_proxy& source) {
    std::allocator<std::_Container_proxy> allocator;
    std::allocator_traits<decltype(allocator)>::construct(allocator, destination, std::move(source));
    (void)std::_Unfancy(destination);
}
int Unk_GuildDriveReverse(Unk_PropertyMap& properties, int limit) {
    int last = properties.rbegin()->first;
    return (std::max)(last, limit);
}
void Unk_GuildDriveAtl(void* buf) {
    new (buf) guilddef4::AtlEventMap();
    new (buf) guilddef4::AtlSkillMap();
    new (buf) guilddef4::AtlNpcMap();
    new (buf) guilddef4::AtlStrMap();
    new (buf) guilddef4::GradeArray();
    new (buf) guilddef4::HistArray();
    new (buf) guilddef4::MemberRBMap(10);
}

// Node-construction and forwarding helpers pulled in by the tree containers above.
template <class Map>
void Unk_DriveNodeForward(Map& map, typename Map::const_iterator& where, typename Map::value_type& value) {
    using Node = std::_Tree_node<typename Map::value_type, void*>;
    std::allocator<Node> allocator;
    std::allocator_traits<std::allocator<Node>>::construct(allocator, &value, value);
    (void)std::forward<typename Map::const_iterator&>(where);
    const typename Map::key_compare compare = map.key_comp();
    (void)std::forward<const typename Map::key_compare&>(compare);
}
void Unk_GuildDriveForward(Unk_StorageMap& storage, Unk_StorageMap::const_iterator& storageWhere, Unk_StorageMap::value_type& storageValue,
                           Unk_NpcShopMap& shops, Unk_NpcShopMap::const_iterator& shopWhere, Unk_NpcShopMap::value_type& shopValue,
                           Unk_NpcMap& npcs, Unk_NpcMap::const_iterator& npcWhere, Unk_NpcMap::value_type& npcValue,
                           Unk_NpcKindSet& kinds, Unk_GuildNpcKind& kind, const Unk_GuildNpcKind& constKind,
                           Unk_HouseMap& houses) {
    Unk_DriveNodeForward(storage, storageWhere, storageValue);
    Unk_DriveNodeForward(shops, shopWhere, shopValue);
    Unk_DriveNodeForward(npcs, npcWhere, npcValue);
    Unk_HouseMap::const_iterator houseWhere = houses.begin();
    Unk_DriveNodeForward(houses, houseWhere, *houses.begin());
    std::allocator<std::_Tree_node<Unk_GuildNpcKind, void*>> allocator;
    std::allocator_traits<decltype(allocator)>::construct(allocator, &kind, constKind);
    (void)std::forward<Unk_GuildNpcKind&>(kind);
    (void)kinds;
}

